<?php
namespace App\Filament\Resources;
use App\Filament\Resources\RedirectRuleResource\Pages; use App\Models\RedirectRule; use App\Services\{AdminAudit,RedirectResolver}; use Filament\Actions\{Action,CreateAction,EditAction}; use Filament\Forms\Components\{Select,TextInput,Toggle}; use Filament\Schemas\Components\Section; use Filament\Schemas\Schema; use Filament\Tables\Columns\TextColumn; use Filament\Tables\Filters\{SelectFilter,TernaryFilter}; use Filament\Tables\Table; use Illuminate\Http\Request;
class RedirectRuleResource extends AdminResource { protected static ?string $model=RedirectRule::class; protected static ?string $recordTitleAttribute='source_path'; protected static string|null|\BackedEnum $navigationIcon='heroicon-o-arrow-uturn-right'; protected static string|\UnitEnum|null $navigationGroup='SEO'; protected static ?string $navigationLabel='Redirections';
 public static function form(Schema $schema):Schema{return $schema->components([Section::make()->columns(2)->schema([TextInput::make('source_path')->label('Source')->required()->maxLength(2048)->helperText('Chemin commençant par / ou expression régulière.'),Select::make('match_type')->options(['exact'=>'Exact','regex'=>'Expression régulière'])->required()->default('exact'),TextInput::make('query_pattern')->maxLength(2048),TextInput::make('destination')->label('Destination')->required()->maxLength(2048),Select::make('status_code')->options([301=>'301 permanent',302=>'302 temporaire',307=>'307 temporaire',308=>'308 permanent',410=>'410 supprimé'])->default(301)->required(),TextInput::make('priority')->numeric()->default(1000)->required(),Toggle::make('is_active')->default(true),Toggle::make('preserve_query')->label('Conserver la query string')])]);}
 public static function table(Table $table):Table{return $table->columns([TextColumn::make('source_path')->label('Source')->searchable()->limit(45),TextColumn::make('destination')->label('Destination')->searchable()->limit(45),TextColumn::make('match_type')->label('Type')->badge(),TextColumn::make('status_code')->label('Code')->badge()->color(fn($state)=>(int)$statetate===301?'success':((int)$statetate===410?'danger':'warning')),TextColumn::make('priority')->sortable(),TextColumn::make('is_active')->label('Actif')->badge()->formatStateUsing(fn($state)=>$state?'Oui':'Non')->color(fn($state)=>$state?'success':'gray'),TextColumn::make('hit_count')->label('Hits')->numeric()->sortable()->toggleable(),TextColumn::make('last_hit_at')->label('Dernier hit')->since()->toggleable()])->filters([SelectFilter::make('match_type')->options(['exact'=>'Exact','regex'=>'Regex']),SelectFilter::make('status_code')->options([301=>'301',302=>'302',307=>'307',308=>'308',410=>'410']),TernaryFilter::make('is_active')->label('Actives')])->recordActions([Action::make('test')->label('Tester')->form([TextInput::make('url')->label('URL / chemin à tester')->required()->default(fn(RedirectRule $r)=>$r->source_path)])->action(function(RedirectRule $r,array $data):void{$result=app(RedirectResolver::class)->resolve(Request::create($data['url'],'GET'));\Filament\Notifications\Notification::make()->title($result?'Règle résolue : '.$result['destination']:'Aucune règle applicable')->success()->send();}),EditAction::make()])->defaultSort('priority')->emptyStateHeading('Aucune redirection');}
 public static function getPages():array{return ['index'=>Pages\ListRedirectRules::route('/'),'create'=>Pages\CreateRedirectRule::route('/create'),'edit'=>Pages\EditRedirectRule::route('/{record}/edit')];}}
